-- ============================================================================
-- USTORE GREENFIELD — 006: DELIVERY REFERENCE DATA (GLOBAL, NOT SHOP-OWNED)
-- ============================================================================
-- 21-band: delivery_branches (BTS/EMU post-office branches) is platform-level
-- reference data shared by every shop on this Supabase project. It carries
-- NO shop_id — a shop merely OPTS a region/provider combination in via its
-- own shop_settings.fulfillment_config; it never owns or edits these rows.
--
-- The 619-row dataset itself is real data (scraped from each provider's own
-- public site — see source_url/source_checked_at on every row for
-- provenance), carried forward unchanged from the old project's migration
-- 015 + the RU columns added in its migration 025 + the index added in its
-- migration 019. Old FITCORE migration numbering/dependency comments are not
-- carried forward — this file is self-contained and depends only on nothing
-- (delivery_branches has no shop_id, so it doesn't even depend on 001).
-- ============================================================================

begin;

create table if not exists public.delivery_branches (
  id bigserial primary key,
  provider text not null check (provider in ('BTS', 'EMU')),
  branch_code text not null,
  region_code text not null,
  district_or_city text,
  district_or_city_ru text,
  branch_name text not null,
  branch_name_ru text,
  full_address text not null,
  full_address_ru text,
  phone text,
  landmark text,
  work_hours text,
  latitude numeric(9,6),
  longitude numeric(9,6),
  active boolean not null default true,
  source_url text not null,
  source_checked_at timestamptz not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (provider, branch_code)
);

comment on table public.delivery_branches is
  'Platform-level BTS/EMU branch reference data, shared across all shops. Not shop-specific. Re-synced periodically from each provider''s own public source; source_url/source_checked_at record provenance.';

create index if not exists delivery_branches_region_provider_idx
  on public.delivery_branches (region_code, provider) where active;

create index if not exists delivery_branches_region_district_idx
  on public.delivery_branches (region_code, district_or_city) where active;

create index if not exists delivery_branches_search_idx
  on public.delivery_branches using gin (
    to_tsvector('simple', coalesce(branch_name,'') || ' ' || coalesce(district_or_city,'') || ' ' || coalesce(full_address,''))
  );

-- Idempotent upsert: safe to re-run this migration (matching provider+
-- branch_code updates in place instead of duplicating). RU columns are
-- deliberately left out of the upsert's SET list, same as the old schema —
-- a re-sync of the UZ source data must never wipe out RU translations
-- already filled in by translate_delivery_branches_batch.
